/// <summary>\n/// Determines whether to show help.\n/// </summary>\npublic static bool ShouldShowHelp(string[] args) {\n    return args.Length > 0 && (args[0] == "--help" || args[0] == "--h");\n}\n\n/// <summary>\n/// Processes the input files.\n/// </summary>\npublic static void ProcessFiles(string[] files) {\n    foreach (var file in files) {\n        // Processing logic here\n        Console.WriteLine($"Processing file: {file}");\n    }\n}\n\n/// <summary>\n/// Gets the time offset.\n/// </summary>\npublic static TimeSpan GetTimeOffset() {\n    // Logic to get time offset\n    return TimeSpan.Zero; // Placeholder\n}\n\n/// <summary>\n/// Gets the output file name based on input file.\n/// </summary>\npublic static string GetOutputFileName(string inputFile) {\n    return $"{Path.GetFileNameWithoutExtension(inputFile)}_output.txt";\n}